let lastFrameTime = 0;
let frameCount = 0;
let fps = 0;

function updateFPS() {
  const now = performance.now();
  frameCount++;

  if (now - lastFrameTime >= 1000) {
    fps = frameCount;
    frameCount = 0;
    lastFrameTime = now;
  }
}

module.exports = {
  updateFPS,
  getFPS: () => fps
};

const fpsElement = document.getElementById('fps');
const storyManager = require('./utils/StoryManager');

function gameLoop() {
  storyManager.updateFPS();
  fpsElement.textContent = `${storyManager.getFPS()} FPS`;
  requestAnimationFrame(gameLoop);
}

requestAnimationFrame(gameLoop);

